def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """

    # split string on spaces into a list of letters
    letters = test.split(" ")
    # create a dictionary to store letter counts
    letter_counts = {}
    # loop over each letter in the list and update the dictionary
    for letter in letters:
        if letter in letter_counts:
            letter_counts[letter] += 1
        else:
            letter_counts[letter] = 1
    # find the maximum count value in the dictionary
    max_count = max(letter_counts.values())
    # create a new dictionary to store the most frequent letters
    result = {}
    # loop over each key-value pair in the dictionary
    for letter, count in letter_counts.items():
        # if the count matches the maximum count, add the letter to the result dictionary
        if count == max_count:
            result[letter] = count
    return result

