def prod_signs(arr):
    """
    You are given an array arr of integers and you need to return
    sum of magnitudes of integers multiplied by product of all signs
    of each number in the array, represented by 1, -1 or 0.
    Note: return None for empty arr.

    Example:
    >>> prod_signs([1, 2, 2, -4]) == -9
    >>> prod_signs([0, 1]) == 0
    >>> prod_signs([]) == None
    """

    if not arr:
        return None

    prod = 1
    sign_count = {'positive': 0, 'negative': 0, 'zero': 0}
    total_sum = 0

    for ele in arr:
        if ele > 0:
            sign_count['positive'] += 1
        elif ele < 0:
            sign_count['negative'] += 1
        else:
            sign_count['zero'] += 1

        prod *= 1 if ele == 0 else ele/abs(ele)
        total_sum += abs(ele)

    return (total_sum * prod)

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """

    def weight(x):
        x_list = list(str(x))
        if x_list[0] == '-':
            x_list = x_list[1:]
            x_list = list(map(int, x_list))
            x_list[0] = -x_list[0]
        else:
            x_list = list(map(int, x_list))
        return sum(x_list)
    return sorted(nums, key=weight)

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """

    def is_prime(a):
        return not (a < 2 or any((a % x == 0 for x in range(2, int(a ** 0.5) + 1))))
    return x if is_prime(n) else y

import math

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    if n < 2:
        return None
    if n == 2:
        return x

    for i in range(2, int(math.sqrt(n))+1):
        if n % i == 0:
            return y

    return x

def Strongest_Extension(class_name, extensions):
    cap_sm_strength = {}
    for ext in extensions:
        CAP = sum(1 for c in ext if c.isupper()) # count of uppercase letters
        SM = len(ext) - CAP # count of lowercase letters
        strength = CAP - SM # calculate strength of extension
        cap_sm_strength[ext] = strength

    # sort the extensions by their strength
    ext_sorted = sorted(cap_sm_strength.items(), key=lambda x: (-x[1], extensions.index(x[0])))

    return f"{class_name}.{ext_sorted[0][0]}"

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    (even, odd) = (0, 0)
    for ch in str(num):
        if ch in '02468':
            even += 1
        if ch in '13579':
            odd += 1
    return (even, odd)

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    even, odd = 0, 0
    num = abs(num)
    while num > 0:
        digit = num % 10
        if digit % 2 == 0:
            even += 1
        else:
            odd += 1
        num //= 10
    return (even, odd)
